// Generated by OrchestKit Claude Plugin
// Created: 2026-09-23
//
// #4218: project-tree orchestration webhook must be ignored.

import { describe, test, expect, beforeEach, afterEach } from 'vitest';
import { existsSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { getWebhookUrl } from '../lib/orchestration-state.js';

const WEBHOOK_ENV_KEYS = [
  'CLAUDE_PLUGIN_OPTION_WEBHOOKURL',
  'ORCHESTKIT_HOOK_URL',
] as const;

let TEST_PROJECT_DIR: string;
let originalEnv: Record<string, string | undefined>;

describe('#4218 orchestration webhook project-tree ignore', () => {
  beforeEach(() => {
    const unique = `${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    TEST_PROJECT_DIR = join(tmpdir(), `orch-webhook-4218-${unique}`);
    originalEnv = {
      CLAUDE_PROJECT_DIR: process.env.CLAUDE_PROJECT_DIR,
      CLAUDE_SESSION_ID: process.env.CLAUDE_SESSION_ID,
    };
    for (const key of WEBHOOK_ENV_KEYS) {
      originalEnv[key] = process.env[key];
      delete process.env[key];
    }
    process.env.CLAUDE_PROJECT_DIR = TEST_PROJECT_DIR;
    process.env.CLAUDE_SESSION_ID = `sess-4218-${unique}`;
    mkdirSync(join(TEST_PROJECT_DIR, '.claude', 'orchestration'), { recursive: true });
  });

  afterEach(() => {
    if (existsSync(TEST_PROJECT_DIR)) {
      rmSync(TEST_PROJECT_DIR, { recursive: true, force: true });
    }
    for (const [key, value] of Object.entries(originalEnv)) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
    for (const key of WEBHOOK_ENV_KEYS) {
      if (originalEnv[key] === undefined) delete process.env[key];
      else process.env[key] = originalEnv[key];
    }
  });

  test('orchestration config.json webhook in the project tree is ignored', () => {
    writeFileSync(
      join(TEST_PROJECT_DIR, '.claude', 'orchestration', 'config.json'),
      JSON.stringify({ webhookUrl: 'https://evil-from-project.example.com' }),
      'utf8'
    );
    expect(getWebhookUrl()).toBeUndefined();
  });

  test('user-scope https webhook via env still resolves', () => {
    process.env.ORCHESTKIT_HOOK_URL = 'https://hooks.example.com';
    expect(getWebhookUrl()).toBe('https://hooks.example.com');
  });

  test('http:// webhook via env is refused', () => {
    process.env.ORCHESTKIT_HOOK_URL = 'http://localhost:8080';
    expect(getWebhookUrl()).toBeUndefined();
  });
});
